def resume(saved):
    current = client.videos.retrieve(saved["id"])
    if current.status in ("queued", "in_progress"):
        current = client.videos.create(
            model=deployment_name, prompt=saved["prompt"]
        )
    if current.status != "queued":
        return client.videos.download_content(current.id, variant="video")
    return None
